/* ==========================================================================
   VARIANT D · ODD — "quirky neighbourhood cinema"     (page-level Custom CSS)
   Paste into Pages → Variant D Odd → page settings → Custom CSS.
   INDY prefixes every rule with .page-variant-d-odd-<id>; nothing leaks.

   COLOURS
   1 BASE TOKENS read Theme & Style (--q-*). Change colours there, not here.
   2 DEMO PALETTE is a test-site override so six personas share one theme.
     On a customer site: delete block 2, set Theme & Style per THEME-PRESETS.md.
   3 DERIVED TOKENS are computed from 1/2 with color-mix(). Do not edit.
   No hex colour appears after block 2.
   ========================================================================== */

/* 1 · BASE TOKENS — keyed to Theme & Style */
[class*="section-"] {
  --v-paper: var(--q-background);   /* page ground      ← Background */
  --v-ink:   var(--q-dark);         /* text, borders    ← Dark */
  --v-go:    var(--q-primary);      /* primary actions  ← Primary */
  --v-stamp: var(--q-secondary);    /* stamps, prices   ← Secondary */
  --v-pop:   var(--q-accent);       /* paper-scrap tint ← Accent */
}

/* 2 · DEMO PALETTE — Adam Template Testing 2 only. Delete on a customer site. */
[class*="section-"] {
  --v-paper: #F5F0E6;
  --v-ink:   #141418;
  --v-go:    #3F6B4E;
  --v-stamp: #A34B3C;
  --v-pop:   #9DBCA6;
}

/* 3 · DERIVED TOKENS — computed, do not edit */
[class*="section-"] {
  --v-white:    color-mix(in oklab, var(--v-paper) 65%, white);
  --v-scrap:    color-mix(in oklab, var(--v-pop) 60%, var(--v-paper));
  --v-scrap-2:  color-mix(in oklab, var(--v-ink) 7%, var(--v-paper));
  --v-line:     color-mix(in oklab, var(--v-ink) 22%, transparent);
  --v-tape:     color-mix(in oklab, var(--v-ink) 18%, transparent);
  --v-muted:    color-mix(in oklab, var(--v-ink) 62%, var(--v-paper));
  --v-on-go:    var(--v-paper);
  --v-on-stamp: var(--v-paper);
  --v-display:  "Bodoni Moda", "Didot", Georgia, serif;
  --v-ui:       "Jost", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --v-mono:     "IBM Plex Mono", ui-monospace, Menlo, monospace;
  --v-ease:     cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* ---- shared ground: paper everywhere, rotated things never cause horizontal scroll ---- */
[class*="section-"] {
  background-color: var(--v-paper);
  color: var(--v-ink);
  font-family: var(--v-ui);
  overflow-x: clip;
}
[class*="section-"] *,
[class*="section-"] *::before,
[class*="section-"] *::after {
  box-sizing: border-box;
}
[class*="section-"] :is(h1, h2, h3, h4) {
  font-family: var(--v-display) !important;
  font-weight: 400 !important;
  font-style: italic;
  letter-spacing: -0.01em;
  line-height: 1.02;
  color: var(--v-ink);
  text-transform: none;
}
[class*="section-"] :is(h1, h2, h3, h4) em {
  font-style: normal;
  color: var(--v-go);
}
/* anything tilted straightens on hover, 220ms, no bounce */
[class*="section-"] .od-tilt {
  transition: transform 220ms var(--v-ease);
}
[class*="section-"] .od-tilt:hover {
  transform: rotate(0deg) !important;
}

/* ==========================================================================
   HERO D · COLLAGE  (Generic Carousel)
   The still is a print taped to the wall; the title breaks out under its
   lower-right edge; the slide Subtitle renders as a dashed stamp holding the
   next showtime; the button is a rust underline.
   ========================================================================== */
[class*="section-hero-d---collage-"] {
  padding: 48px 0 8px;
}
[class*="section-hero-d---collage-"] .swiper-slide .row.justify-center.position-relative {
  display: block !important;
  height: auto !important;
  min-height: 0 !important;
  padding: 16px 28% 0 8%;
}
[class*="section-hero-d---collage-"] img.full-width {
  display: block;
  width: 100%;
  height: auto;
  padding: 10px 10px 36px;
  background-color: var(--v-white);
  border: 1px solid var(--v-ink);
  transform: rotate(-1.5deg);
  box-shadow: none;
}
[class*="section-hero-d---collage-"] .swiper-slide:nth-child(even) img.full-width {
  transform: rotate(1.2deg);
}
/* the overlay flows under the print instead of sitting on it */
[class*="section-hero-d---collage-"] .flex.absolute-bottom {
  position: static !important;
  display: block !important;
  height: auto !important;
  padding: 0 !important;
  margin-top: -0.55em;
}
[class*="section-hero-d---collage-"] .flex.absolute-bottom .container {
  max-width: none !important;
  padding: 0 !important;
}
[class*="section-hero-d---collage-"] .col.message {
  text-align: right !important;
  padding: 0 6% 0 8% !important;
}
[class*="section-hero-d---collage-"] .title {
  display: inline-block;
  position: relative;
  z-index: 2;
  margin: 0 !important;
  font-family: var(--v-display) !important;
  font-style: italic;
  font-weight: 400 !important;
  font-size: clamp(44px, 6.2vw, 80px) !important;
  line-height: 0.95 !important;
  letter-spacing: -0.02em;
  color: var(--v-ink) !important;
  text-shadow: none !important;
  transform: rotate(-2deg);
  transform-origin: right top;
}
/* Subtitle field = the stamp. Write the next showtime there, e.g. "Tonight 7:30". */
[class*="section-hero-d---collage-"] .subtitle {
  position: absolute;
  top: 0;
  right: 20%;
  z-index: 3;
  width: 120px;
  height: 120px;
  display: flex !important;
  align-items: center;
  justify-content: center;
  margin: 0 !important;
  padding: 10px;
  text-align: center;
  background-color: var(--v-scrap);
  border: 1px dashed var(--v-ink);
  color: var(--v-ink) !important;
  font-family: var(--v-mono) !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  line-height: 1.3;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-shadow: none !important;
  transform: rotate(4deg);
}
[class*="section-hero-d---collage-"] .subtitle:empty {
  display: none !important;
}
/* slide button = a rust underline, not a pill */
[class*="section-hero-d---collage-"] .col.message .q-btn {
  background: transparent !important;
  color: var(--v-ink) !important;
  box-shadow: none !important;
  border: 0 !important;
  border-bottom: 2px solid var(--v-stamp) !important;
  border-radius: 0 !important;
  padding: 0 0 2px !important;
  margin: 10px 0 0 !important;
  min-height: 0 !important;
  font-family: var(--v-mono) !important;
  font-size: 13px !important;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
[class*="section-hero-d---collage-"] .col.message .q-btn :is(.q-btn__content, span) {
  color: var(--v-ink) !important;
}
/* dots as small dashed squares, arrows in ink */
[class*="section-hero-d---collage-"] .swiper-pagination {
  position: static;
  margin-top: 8px;
  padding-right: 8%;
  text-align: right;
}
[class*="section-hero-d---collage-"] .swiper-pagination-bullet {
  width: 12px !important;
  height: 12px !important;
  margin: 0 4px !important;
  border-radius: 0 !important;
  background: transparent !important;
  border: 1px dashed var(--v-ink);
  opacity: 1 !important;
}
[class*="section-hero-d---collage-"] .swiper-pagination-bullet-active {
  background: var(--v-ink) !important;
}
[class*="section-hero-d---collage-"] :is(.swiper-button-prev, .swiper-button-next) {
  color: var(--v-ink) !important;
  text-shadow: none !important;
}

/* ==========================================================================
   HERO D · RUTH LINE  (Rich Text) — one mono line under the collage
   ========================================================================== */
[class*="section-hero-d---ruth-line-"] {
  padding: 0 8% 40px;
}
[class*="section-hero-d---ruth-line-"] .od-line {
  margin: 0;
  font-family: var(--v-mono);
  font-size: 13px;
  letter-spacing: 0.04em;
  color: var(--v-muted);
}
[class*="section-hero-d---ruth-line-"] .od-line em {
  font-style: normal;
  color: var(--v-stamp);
}

/* ==========================================================================
   NOW PLAYING D · PINBOARD  (Showtimes widget, grid)
   Each film is an index card pinned to the board; dates are dashed chips.
   ========================================================================== */
[class*="section-now-playing-d---pinboard-"] {
  padding: 48px 16px 72px;
}
[class*="section-now-playing-d---pinboard-"] .heading.container {
  max-width: 1200px !important;
}
[class*="section-now-playing-d---pinboard-"] .text-primary {
  color: var(--v-ink) !important;
}
[class*="section-now-playing-d---pinboard-"] .text-h2 {
  font-family: var(--v-display) !important;
  font-style: italic;
  font-weight: 400 !important;
  font-size: clamp(40px, 5vw, 56px) !important;
  color: var(--v-ink) !important;
}
/* date rail */
[class*="section-now-playing-d---pinboard-"] .calendar-filter {
  padding-top: 8px !important;
}
[class*="section-now-playing-d---pinboard-"] .date-selector-list {
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center !important;
  gap: 10px;
}
[class*="section-now-playing-d---pinboard-"] .date-btn {
  min-width: 64px !important;
  margin: 0 !important;
  background: var(--v-white) !important;
  border: 1px dashed var(--v-ink) !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  transform: rotate(-1.5deg);
  transition: transform 220ms var(--v-ease);
}
[class*="section-now-playing-d---pinboard-"] .date-btn:nth-child(even) {
  transform: rotate(1.5deg);
}
[class*="section-now-playing-d---pinboard-"] .date-btn:hover {
  transform: rotate(0deg);
}
[class*="section-now-playing-d---pinboard-"] .date-btn * {
  font-family: var(--v-mono) !important;
  letter-spacing: 0.04em !important;
  color: var(--v-ink) !important;
}
[class*="section-now-playing-d---pinboard-"] .date-btn.active {
  background: var(--v-ink) !important;
  border-style: solid !important;
}
[class*="section-now-playing-d---pinboard-"] .date-btn.active * {
  color: var(--v-paper) !important;
}
/* keep the widget's own calendar glyphs intact after the font override */
[class*="section-now-playing-d---pinboard-"] .date-btn i.material-icons,
[class*="section-now-playing-d---pinboard-"] .date-btn .q-icon {
  font-family: "Material Icons" !important;
  font-weight: 400 !important;
  font-style: normal !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}
/* film cards */
[class*="section-now-playing-d---pinboard-"] [data-test-id="showtimes-by-film"] {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 28px;
  max-width: 1200px;
  margin: 24px auto 0;
}
[class*="section-now-playing-d---pinboard-"] .movie-container {
  position: relative;
  margin: 0 !important;
  padding: 16px !important;
  background: var(--v-white) !important;
  border: 1px solid var(--v-ink) !important;
  border-radius: 2px !important;
  transform: rotate(var(--tilt, -1.2deg));
  transition: transform 220ms var(--v-ease);
}
[class*="section-now-playing-d---pinboard-"] .movie-container:nth-child(3n+2) { --tilt: 1.6deg; }
[class*="section-now-playing-d---pinboard-"] .movie-container:nth-child(3n) { --tilt: -0.6deg; }
[class*="section-now-playing-d---pinboard-"] .movie-container:hover {
  transform: rotate(0deg);
}
[class*="section-now-playing-d---pinboard-"] .movie-container::before {
  content: "";
  position: absolute;
  top: -8px;
  left: 50%;
  width: 48px;
  height: 14px;
  margin-left: -24px;
  background: var(--v-tape);
  transform: rotate(-3deg);
}
[class*="section-now-playing-d---pinboard-"] .movie-container > .absolute-full {
  display: none !important;
}
[class*="section-now-playing-d---pinboard-"] .movie-container > .row.container {
  flex-wrap: nowrap !important;
  align-items: flex-start !important;
  gap: 14px;
  padding: 0 !important;
}
[class*="section-now-playing-d---pinboard-"] .movie-container .q-img {
  border: 1px solid var(--v-ink);
  border-radius: 0 !important;
}
[class*="section-now-playing-d---pinboard-"] .movie-container .text-h5 {
  font-family: var(--v-display) !important;
  font-style: italic;
  font-weight: 400 !important;
  font-size: 26px !important;
  line-height: 1.05 !important;
  letter-spacing: -0.01em !important;
  text-transform: none !important;
  color: var(--v-ink) !important;
}
[class*="section-now-playing-d---pinboard-"] .movie-container :is(.text-body2, .text-caption, p) {
  font-family: var(--v-mono) !important;
  font-size: 12px !important;
  color: var(--v-muted) !important;
}
/* showtimes = rust-underlined mono links */
[class*="section-now-playing-d---pinboard-"] .showings .q-btn {
  margin: 6px 14px 0 0 !important;
  padding: 0 0 2px !important;
  min-height: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-bottom: 2px solid var(--v-stamp) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-family: var(--v-mono) !important;
  font-size: 15px !important;
  color: var(--v-ink) !important;
}
[class*="section-now-playing-d---pinboard-"] .showings .q-btn :is(.q-btn__content, span) {
  color: var(--v-ink) !important;
}
/* empty state — a note on the board, not an error */
[class*="section-now-playing-d---pinboard-"] .no-schedule-message {
  max-width: 420px;
  margin: 24px auto !important;
  padding: 32px !important;
  background: var(--v-scrap);
  border: 1px dashed var(--v-ink);
  transform: rotate(-1deg);
}
[class*="section-now-playing-d---pinboard-"] .no-schedule-message .q-icon {
  color: var(--v-ink) !important;
}
[class*="section-now-playing-d---pinboard-"] .no-schedule-message .message {
  font-family: var(--v-display) !important;
  font-style: italic;
  font-size: 28px;
  color: var(--v-ink) !important;
}

/* ==========================================================================
   EVENTS D · NOTICEBOARD  (Rich Text, markup in sections/04-events-d-noticeboard.html)
   12-column board; notes span 3/4/5/6 columns, each at its own angle, with
   a tape strip. One dashed "ask us anything" note links to the postcard.
   ========================================================================== */
[class*="section-events-d---noticeboard-"] {
  padding: 64px 16px 72px;
}
[class*="section-events-d---noticeboard-"] .od-board {
  max-width: 1200px;
  margin: 0 auto;
}
[class*="section-events-d---noticeboard-"] .od-board__eyebrow {
  margin: 0 0 8px;
  font-family: var(--v-mono);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--v-stamp);
}
[class*="section-events-d---noticeboard-"] .od-board__head {
  max-width: 16ch;
  margin: 0 0 40px;
  font-size: clamp(40px, 5vw, 64px);
}
[class*="section-events-d---noticeboard-"] .od-board__grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 28px 24px;
  align-items: start;
}
[class*="section-events-d---noticeboard-"] .od-note {
  position: relative;
  grid-column: span 4;
  padding: 28px 24px 24px;
  background: var(--v-white);
  border: 1px solid var(--v-ink);
  border-radius: 2px;
  transform: rotate(var(--tilt, -2deg));
  transition: transform 220ms var(--v-ease);
}
[class*="section-events-d---noticeboard-"] .od-note:hover {
  transform: rotate(0deg);
}
[class*="section-events-d---noticeboard-"] .od-note::before {
  content: "";
  position: absolute;
  top: -7px;
  left: 50%;
  width: 44px;
  height: 12px;
  margin-left: -22px;
  background: var(--v-tape);
  transform: rotate(-2deg);
}
[class*="section-events-d---noticeboard-"] .od-note--w3 { grid-column: span 3; }
[class*="section-events-d---noticeboard-"] .od-note--w5 { grid-column: span 5; }
[class*="section-events-d---noticeboard-"] .od-note--w6 { grid-column: span 6; }
[class*="section-events-d---noticeboard-"] .od-note--scrap { background: var(--v-scrap); }
[class*="section-events-d---noticeboard-"] .od-note--scrap2 { background: var(--v-scrap-2); }
[class*="section-events-d---noticeboard-"] .od-note--ask {
  background: transparent;
  border-style: dashed;
}
[class*="section-events-d---noticeboard-"] .od-note--ask::before {
  display: none;
}
[class*="section-events-d---noticeboard-"] .od-note:nth-child(2) { --tilt: 2deg; }
[class*="section-events-d---noticeboard-"] .od-note:nth-child(3) { --tilt: -1deg; }
[class*="section-events-d---noticeboard-"] .od-note:nth-child(4) { --tilt: 3deg; }
[class*="section-events-d---noticeboard-"] .od-note:nth-child(5) { --tilt: -3deg; }
[class*="section-events-d---noticeboard-"] .od-note:nth-child(6) { --tilt: 1.5deg; }
[class*="section-events-d---noticeboard-"] .od-note:nth-child(7) { --tilt: -1.5deg; }
[class*="section-events-d---noticeboard-"] .od-note__kicker {
  margin: 0 0 10px;
  font-family: var(--v-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--v-muted);
}
[class*="section-events-d---noticeboard-"] .od-note h3 {
  margin: 0 0 14px;
  font-size: clamp(26px, 2.6vw, 34px);
}
[class*="section-events-d---noticeboard-"] :is(.od-note--w5, .od-note--w6) h3 {
  font-size: clamp(30px, 3.4vw, 48px);
}
[class*="section-events-d---noticeboard-"] .od-note__detail {
  margin: 0 0 18px;
  font-family: var(--v-mono);
  font-size: 12px;
  line-height: 1.6;
  color: var(--v-ink);
}
[class*="section-events-d---noticeboard-"] .od-note__link {
  display: inline-block;
  padding-bottom: 2px;
  border-bottom: 2px solid var(--v-stamp);
  font-family: var(--v-mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--v-ink);
}
[class*="section-events-d---noticeboard-"] .od-note--ask .od-note__link {
  display: inline-block;
  padding: 12px 16px;
  border: 0;
  background: var(--v-go);
  color: var(--v-on-go);
  transform: rotate(2deg);
}

/* ==========================================================================
   FOOD D · STICKER SHEET  (Concessions Menu, grid, 4-up)
   Chips above the sheet, square photo on top of each white card, no two
   cards at the same angle, the price is a rust sticker on the corner.
   ========================================================================== */
[class*="section-food-d---sticker-sheet-"] {
  padding: 32px 16px 80px;
}
[class*="section-food-d---sticker-sheet-"] .container {
  max-width: 1200px !important;
}
[class*="section-food-d---sticker-sheet-"] .container .row {
  justify-content: flex-start !important;
}
[class*="section-food-d---sticker-sheet-"] .container h2 {
  font-family: var(--v-display) !important;
  font-style: italic;
  font-weight: 400 !important;
  font-size: clamp(40px, 5vw, 56px) !important;
  text-align: left !important;
  color: var(--v-ink) !important;
}
/* the widget description = the mono aside ("we make these ourselves") */
[class*="section-food-d---sticker-sheet-"] .text-body1 {
  max-width: 1200px !important;
  margin: 0 auto !important;
  padding: 0 !important;
  text-align: left !important;
  font-family: var(--v-mono) !important;
  font-size: 12px !important;
  color: var(--v-muted) !important;
}
/* rail → a row of dashed chips */
[class*="section-food-d---sticker-sheet-"] .full-width.q-py-md.row {
  flex-direction: column;
  max-width: 1200px;
  margin: 0 auto;
}
[class*="section-food-d---sticker-sheet-"] .col-2 {
  width: 100% !important;
  max-width: 100% !important;
  flex: 0 0 100% !important;
  padding: 0 0 20px !important;
}
[class*="section-food-d---sticker-sheet-"] .category-filter-column {
  position: static !important;
  height: auto !important;
}
[class*="section-food-d---sticker-sheet-"] :is(.q-scrollarea__container, .q-scrollarea__content) {
  position: static !important;
  height: auto !important;
}
[class*="section-food-d---sticker-sheet-"] .q-scrollarea__content {
  display: flex !important;
  flex-wrap: wrap;
  gap: 10px;
}
[class*="section-food-d---sticker-sheet-"] .q-scrollarea__content > .full-width {
  width: auto !important;
}
[class*="section-food-d---sticker-sheet-"] :is(.q-scrollarea__bar, .q-scrollarea__thumb) {
  display: none !important;
}
[class*="section-food-d---sticker-sheet-"] .category-filter-column .q-btn {
  width: auto !important;
  min-height: 0 !important;
  padding: 8px 14px !important;
  background: var(--v-white) !important;
  border: 1px dashed var(--v-ink) !important;
  border-radius: 2px !important;
  font-family: var(--v-mono) !important;
  font-size: 12px !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--v-ink) !important;
  transform: rotate(-1.5deg);
  transition: transform 220ms var(--v-ease);
}
[class*="section-food-d---sticker-sheet-"] .q-scrollarea__content > .full-width:nth-child(even) .q-btn {
  transform: rotate(1.5deg);
}
[class*="section-food-d---sticker-sheet-"] .category-filter-column .q-btn:hover {
  transform: rotate(0deg);
}
[class*="section-food-d---sticker-sheet-"] .category-filter-column .q-btn :is(.q-btn__content, span) {
  color: var(--v-ink) !important;
}
[class*="section-food-d---sticker-sheet-"] .category-filter-column .q-btn:is(.active, .q-btn--active, [aria-pressed="true"]) {
  background: var(--v-ink) !important;
  border-style: solid !important;
